from pathlib import Path
import base64
import gzip
import subprocess
import sys
import tempfile

PATCH_GZ_B64 = ""

def main() -> None:
    target = Path(sys.argv[1]).resolve()
    patch_bytes = gzip.decompress(base64.b64decode(PATCH_GZ_B64))
    with tempfile.NamedTemporaryFile(prefix="bubbles_v38_", suffix=".patch", delete=False) as handle:
        handle.write(patch_bytes)
        patch_path = Path(handle.name)
    try:
        subprocess.run(["patch", "-p0", "-i", str(patch_path)], cwd=target.parent, check=True)
    finally:
        patch_path.unlink(missing_ok=True)
    print(f"v3.8 professional cloud/flag UI applied to {target}")

if __name__ == "__main__":
    main()
